"""Independent union-of-rectangles coverage and Float64 affine pixel oracle."""
from pathlib import Path
import numpy as np,json,hashlib,sys
p=Path(__file__).resolve().parent;s=json.loads((p/'study_shape.json').read_text());W,H=s['width'],s['height'];image=np.fromfile(p/'study_input_f32.bin',dtype='<f4').reshape(H,W,3);boxes=np.fromfile(p/'study_boxes_i32.bin',dtype='<i4').reshape(-1,4);bw,bh,left,top=boxes.T;assert np.isfinite(image).all()and(len(boxes)==s['boxes'])and(left>=0).all()and(top>=0).all();right=np.minimum(left+bw,W);bottom=np.minimum(top+bh,H);diff=np.zeros((H+1,W+1),dtype=np.int64)
for ys,xs,change in [(top,left,1),(top,right,-1),(bottom,left,-1),(bottom,right,1)]:np.add.at(diff,(ys,xs),change)
coverage=diff.cumsum(axis=0).cumsum(axis=1)[:H,:W];assert (coverage>=0).all();mask=coverage>0;alpha=np.float32(1)/np.float32(255);ialph=np.float32(1)-alpha;out=image.astype(np.float64);color=np.array([255,204,203],dtype=np.float64);out[mask]=float(alpha)*color+float(ialph)*out[mask];assert np.isfinite(out).all();(p/'study_expected_f64.bin').write_bytes(out.astype('<f8').tobytes());(p/'study_coverage_u8.bin').write_bytes(mask.astype(np.uint8).tobytes());files={}
for name in ['study_input_f32.bin','study_boxes_i32.bin','study_expected_f64.bin','study_coverage_u8.bin']:
 f=p/name;files[name]={'bytes':f.stat().st_size,'sha256':hashlib.sha256(f.read_bytes()).hexdigest()}
(p/'fixture_provenance.json').write_text(json.dumps({'benchmark':'overlay','source_shape':s,'source_rng':'Original C++srand123 and rand%256 RGB draws followedbyallBox width/height/left/top draws, exactsourceorder; original640x480/0.8pixelboxcount','oracle':'Independent2Ddifference-arrayrectangleunion, clippingupperimagebounds; commoncolor andalways-original-input reads imply oneaffineblendpercoveredpixel, not repeatedblend. Float64arithmetic withactualFloat32alpha/ialph.','numpy':np.__version__,'python':sys.version,'covered_pixels':int(mask.sum()),'uncovered_pixels':int((~mask).sum()),'max_overlap_count':int(coverage.max()),'alpha_float32':float(alpha),'one_minus_alpha_float32':float(ialph),'input_prefix_values_float64':W*H*3+len(boxes)*4+7,'output_rgb_values':W*H*3,'files':files},indent=2)+'\n');print('boxes',len(boxes),'covered',int(mask.sum()),'uncovered',int((~mask).sum()),'maximumoverlaps',coverage.max(),'alpha',alpha)
